from sklearn.utils import resample

# Function to calculate the percentage of respondents indicating that they use a documentation format
def calculate_percentage(col):
    return (df[col].value_counts(normalize=True) * 100).round(3)

# Function to perform bootstrapping
def bootstrap_percentage(col, n_samples=1000):
    percentages = []
    for _ in range(n_samples):
        sample = resample(df[col], replace=True, n_samples=len(df[col]), random_state=None)
        percentage = calculate_percentage(sample)
        percentages.append(percentage)
    return np.percentile(percentages, [2.5, 97.5])

# Perform bootstrapping for each documentation format
bootstrap_results = {}
for col in documentation_columns:
